    if (!svg_index_element_at(session, 1U, &e) || e.support != SVG_INDEX_SUPPORTED_RECT ||
        e.depth != 1U || e.parent != 0U || !e.closed || e.source_offset != rect_offset ||
        e.source_length != rect_length ||
